You are given a list of products, each with a name and a price. You are also given a list of promotions with their associated promo codes and discounts. Write a function that takes in the list of products, an optional promo code, and a target price range. The function should calculate the total cost after applying any applicable discounts and return the number of items in the shopping cart that fall within the specified price range, along with the average price per item in the shopping cart.
struct Product {
    var name: String
    var price: Double
}
struct Promotion {
    var promoCode: String
    var discount: Double
}
var productList = [Product(name: "Shirt", price: 25.00), Product(name: "Pants", price: 40.00)]
var promotions = [Promotion(promoCode: "SAVE10", discount: 0.10), Promotion(promoCode: "SAVE20", discount: 0.20)]
func calculateTotalCost(cart: [Product], promoCode: String? = nil, targetPriceRange: ClosedRange<Double>) -> (Double, Int, Double) {
    var totalCost = 0.0
    var count = 0
    for product in cart {
        totalCost += product.price
        if targetPriceRange.contains(product.price) {
            count += 1
        }
    }
    if let promoCode = promoCode {
        for promotion in promotions {
            if promotion.promoCode == promoCode {
                totalCost *= (1 - promotion.discount)
            }
        }
    }
    let averagePrice = totalCost / Double(cart.count)
    return (totalCost, count, averagePrice)
}
print(calculateTotalCost(cart: productList, targetPriceRange: 20.0...30.0))
print(calculateTotalCost(cart: productList, promoCode: "SAVE10", targetPriceRange: 20.0...30.0))

