$romeo_and_juliet_stems = array_map([$stemmer, 'stem'], $romeo_and_juliet_tokens);
$shakespeare_stems = array_map([$stemmer, 'stem'], $shakespeare_tokens);
// Compute the similarity between the main theme in Romeo and Juliet and other works of Shakespeare
$main_theme = ['love', 'death', 'tragedy'];
$cosine_similarity = new CosineSimilarity();
$romeo_and_juliet_similarity = $cosine_similarity->similarity($main_theme, $romeo_and_juliet_stems);
$shakespeare_similarity = $cosine_similarity->similarity($main_theme, $shakespeare_stems);
// Generate a comparison report
echo "Similarity between Romeo and Juliet and other works of Shakespeare based on the main theme:\n";
echo "- Romeo and Juliet: " . $romeo_and_juliet_similarity . "\n";
echo "- Other works of Shakespeare: " . $shakespeare_similarity . "\n";
