using namespace std;
double mean(double arr[], int n) {
    double sum = 0;
    for(int i = 0; i < n; i++) {
        sum += arr[i];
    }
    return sum/n;
}
double variance(double arr[], int n) {
    double sum = 0;
    double mean_val = mean(arr, n);
    for(int i = 0; i < n; i++) {
        sum += pow((arr[i] - mean_val), 2);
    }
    return sum/n;
}
double covariance(double arr1[], double arr2[], int n) {
    double sum = 0;
    double mean1 = mean(arr1, n);
    double mean2 = mean(arr2, n);
    for(int i = 0; i < n; i++) {
        sum += (arr1[i] - mean1)*(arr2[i] - mean2);
    }
    return sum/n;
}
double regression_slope(double arr1[], double arr2[], int n) {
    double cov = covariance(arr1, arr2, n);
    double var = variance(arr1, n);
    return cov/var;
}
double regression_intercept(double arr1[], double arr2[], int n) {
    double slope = regression_slope(arr1, arr2, n);
    double mean1 = mean(arr1, n);
    double mean2 = mean(arr2, n);
