// Define a function to simulate the crossing process
func cross(_ a: Int, _ b: Int, _ left: [Int], _ right: [Int]) -> Bool {
    // If there's only one person left on the left bank, they can't cross
    if left.count == 1 {
        return false
    }
    // If both people on the left bank can't cross together, they have to cross separately
    if !canCross(left[0], left[1]) {
