Here's a code snippet that demonstrates how to extract and visualize the top 10 most frequent terms in a corpus of scientific research papers using C#:
```
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
namespace TopTerms
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the corpus of research papers
            string corpusPath = @"C:\corpus";
            var corpus = LoadCorpus(corpusPath);
            // Extract the terms from the corpus
            var terms = ExtractTerms(corpus);
            // Get the top 10 most frequent terms
            var topTerms = GetTopTerms(terms, 10);
            // Print the top terms
            foreach (var term in topTerms)
            {
                Console.WriteLine("{0}: {1}", term.Key, term.Value);
            }
        }
        static List<string> LoadCorpus(string path)
        {
            var corpus = new List<string>();
            // Load all text files in the directory
            var files = Directory.GetFiles(path, "*.txt");
            foreach (var file in files)
            {
                corpus.Add(File.ReadAllText(file));
            }
            return corpus;
        }
        static Dictionary<string, int> ExtractTerms(List<string> corpus)
        {
            var terms = new Dictionary<string, int>();
            // Extract all terms from the corpus
            foreach (var document in corpus)
            {
                var words = Regex.Split(document.ToLower(), @"\W+");
                foreach (var word in words)
                {
                    if (!string.IsNullOrEmpty(word))
                    {
                        if (terms.ContainsKey(word))
                        {
                            terms[word]++;
                        }
                        else
                        {
                            terms[word] = 1;
                        }
                    }
                }
            }
            return terms;
        }
        static List<KeyValuePair<string, int>> GetTopTerms(Dictionary<string, int> terms, int count)
        {
            var topTerms = terms.OrderByDescending(x => x.Value).Take(count).ToList();
            return topTerms;
        }
    }
}
```
This code loads a corpus of research papers from a directory, extracts all terms from the corpus, and then gets the top 10 most frequent terms. The terms are extracted using a regular expression to split the text into words, and a dictionary is used to count the frequency of each term. The top terms are then sorted by frequency and the top 10 are returned.

