    public List<String> generateRecommendations(Map<String, Integer> purchaseHistory) {
        Map<String, Double> itemScores = new HashMap<>();
        // calculate item scores based on purchase history
        for (String item : purchaseHistory.keySet()) {
            int quantity = purchaseHistory.get(item);
            double price = itemPrices.get(item);
            List<String> categories = itemCategories.get(item);
            for (String category : categories) {
                double preference = customerPreferences.get(category);
                double spendingHabit = customerSpendingHabits.get(category);
                double score = preference * spendingHabit * quantity / price;
                if (itemScores.containsKey(item)) {
                    score += itemScores.get(item);
                }
                itemScores.put(item, score);
            }
        }
        // sort items by score
        List<String> recommendations = new ArrayList<>(itemScores.keySet());
        recommendations.sort((item1, item2) -> Double.compare(itemScores.get(item2), itemScores.get(item1)));
        return recommendations;
    }
    public static void main(String[] args) {
        SalesRecommendations salesRecommendations = new SalesRecommendations();
        // example purchase history
        Map<String, Integer> purchaseHistory = new HashMap<>();
        purchaseHistory.put("item1", 2);
        purchaseHistory.put("item2", 1);
        purchaseHistory.put("item3", 3);
