        String path = wnhome + "/dict";
        IDictionary dict = new edu.mit.jwi.Dictionary(new java.io.File(path));
        dict.open();
        // Input sentence and synonyms
        String sentence = "The weather is cold today.";
        Map<String, List<String>> synonyms = new HashMap<>();
        synonyms.put("cold", Arrays.asList("chilly", "freezing", "frigid", "icy"));
        // Perform antonymous substitutions
        List<String> antonyms = new ArrayList<>();
        for (String word : sentence.split("\\s+")) {
            String pos = getPOS(word); // Get word's POS
            if (pos != null && synonyms.containsKey(word)) {
                for (String syn : synonyms.get(word)) {
                    IIndexWord idxWord = dict.getIndexWord(syn, getWordNetPOS(pos)); // Get WordNet index word
                    if (idxWord != null) {
                        for (IWordID wordID : idxWord.getWordIDs()) {
                            IWord iword = dict.getWord(wordID);
                            for (ISynset synset : iword.getSynset().getRelatedSynsets(Pointer.ANTONYM)) {
                                for (IWord ant : synset.getWords()) {
                                    antonyms.add(ant.getLemma());
                                }
                            }
                        }
                    }
                }
            }
        }
        // Generate alternate sentences
        Set<String> sentences = new HashSet<>();
        for (String antonym : antonyms) {
            String altSentence = sentence;
            for (String word : sentence.split("\\s+")) {
                if (synonyms.containsKey(word) && synonyms.get(word).contains(antonym)) {
                    altSentence = altSentence.replace(word, antonym);
                }
            }
            sentences.add(altSentence);
        }
        // Print alternate sentences
        for (String altSentence : sentences) {
            System.out.println(altSentence);
        }
        // Close WordNet dictionary
        dict.close();
    }
