    }
    // Map POS tags to WordNet POS
    private static POS getWordNetPOS(String pos) {
        switch (pos) {
            case "NN":
            case "NNS":
            case "NNP":
            case "NNPS":
                return POS.NOUN;
            case "VB":
            case "VBD":
            case "VBG":
            case "VBN":
            case "VBP":
            case "VBZ":
                return POS.VERB;
            case "JJ":
