import NaturalLanguage
let text = "I think only young people can be successful in the tech industry."
let target = ["young"]
let non_target = ["successful", "tech industry"]
// Preprocess the text
let tokenizer = NLTokenizer(unit: .word)
tokenizer.string = text.lowercased()
let words = tokenizer.tokens(for: text.startIndex..<text.endIndex).map { String(text[$0]) }
let filteredWords = words.filter { !NLTagger.isStopWord($0) }
// Create a bag of words
var bagOfWords = [String: Int]()
for word in filteredWords {
    if let count = bagOfWords[word] {
        bagOfWords[word] = count + 1
    } else {
        bagOfWords[word] = 1
    }
}
// Create feature vectors
