        // Train neural network using backpropagation
        for (int epoch = 0; epoch < NUM_EPOCHS; epoch++) {
            double[] delta1 = new double[NUM_HIDDEN_UNITS * (NUM_FEATURES + 1)];
            double[] delta2 = new double[NUM_HIDDEN_UNITS + 1];
            for (int i = 0; i < X.length; i++) {
                double[] a1 = new double[NUM_HIDDEN_UNITS];
                for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
                    double z = 0.0;
                    for (int k = 0; k < NUM_FEATURES; k++) {
                        z += X[i][k] * theta1[j * NUM_FEATURES + k];
                    }
                    z += theta1[j * NUM_FEATURES + NUM_FEATURES];
                    a1[j] = sigmoid(z);
                }
                double z2 = 0.0;
                for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
                    z2 += a1[j] * theta2[j];
                }
                z2 += theta2[NUM_HIDDEN_UNITS];
                double h = sigmoid(z2);
                double delta3 = h - y[i];
                for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
                    delta2[j] += delta3 * a1[j];
                }
                delta2[NUM_HIDDEN_UNITS] += delta3;
                for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
                    double delta = delta3 * theta2[j] * sigmoidGradient(a1[j]);
                    for (int k = 0; k < NUM_FEATURES; k++) {
                        delta1[j * NUM_FEATURES + k] += delta * X[i][k];
                    }
                    delta1[j * NUM_FEATURES + NUM_FEATURES] += delta;
                }
            }
            for (int i = 0; i < theta2.length; i++) {
                theta2[i] -= LEARNING_RATE * (delta2[i] + REGULARIZATION_PARAM * theta2[i]);
            }
            for (int i = 0; i < theta1.length; i++) {
                theta1[i] -= LEARNING_RATE * (delta1[i] + REGULARIZATION_PARAM * theta1[i]);
            }
        }
    }
    private static double predict(double[] input) {
        double[] a1 = new double[NUM_HIDDEN_UNITS];
        for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
            double z = 0.0;
            for (int k = 0; k < NUM_FEATURES; k++) {
                z += input[k] * theta1[j * NUM_FEATURES + k];
            }
            z += theta1[j * NUM_FEATURES + NUM_FEATURES];
            a1[j] = sigmoid(z);
        }
        double z2 = 0.0;
        for (int j = 0; j < NUM_HIDDEN_UNITS; j++) {
            z2 += a1[j] * theta2[j];
        }
        z2 += theta2[NUM_HIDDEN_UNITS];
        double h = sigmoid(z2);
        return h;
    }
    private static double sigmoid(double z) {
        return 1.0 / (1.0 + Math.exp(-z));
    }
    private static double sigmoidGradient(double z) {
        double s = sigmoid(z);
        return s * (1.0 - s);
    }
}
```
