```
struct KnockKnockJoke {
    let setup: String
    let punchline: String
    let humorLevel: Int
    let complexity: Int
    var length: Int {
        return setup.count + punchline.count
    }
}
let vegetables = ["lettuce", "carrot", "cucumber", "broccoli", "celery"]
let response = ["Lettuce in, it's cold out here!", "Carrot who?", "Cucumber all this way, I hope you have a good joke!", "Broccoli doesn't have a last name, silly!", "Celerybrate good times, come on!"]
