for i in 0..<vegetables.count {
    let joke = KnockKnockJoke(setup: "Knock, knock. Who's there? " + vegetables[i] + ". ", punchline: response[i], humorLevel: 5, complexity: 3)
    jokes.append(joke)
}
// Sort the jokes by humor level, complexity, and length
jokes.sort {
    if $0.humorLevel != $1.humorLevel {
        return $0.humorLevel > $1.humorLevel
    } else if $0.complexity != $1.complexity {
        return $0.complexity < $1.complexity
    } else {
        return $0.length < $1.length
    }
}
// Print the jokes in a table
