print("------------------------------------------------------------------")
for joke in jokes {
    print("\(joke.humorLevel)\t\(joke.complexity)\t\t\(joke.length)\t\(joke.setup)\(String(repeating: " ", count: 30 - joke.setup.count))\(joke.punchline)")
}
```
